/// All imported strategies, in registration order.
pub fn all() -> &'static [ImportedStrategy] {
    STRATEGIES
}

/// Looks an imported strategy up by its id.
pub fn find(id: &str) -> Option<&'static ImportedStrategy> {
    STRATEGIES.iter().find(|s| s.id == id)
}

/// Whether `id` belongs to an imported strategy (the
/// supervisor reports the split-tunnel mode as not applied
/// for these, like for the flagship: their argument lists
/// are fixed data, the Lua tunnel modes do not reshape them).
pub fn is_imported(id: &str) -> bool {
    find(id).is_some()
}

/// Payload file for a blob name, mirroring the subset of
/// the collection's blobs.lua that these strategies use.
/// The files ship in the engine bin/ (upstream zapret2 /
/// Flowseal bin folder); registration is ours.
pub fn blob_file(name: &str) -> Option<&'static str> {
    Some(match name {
        "active_discord" => "ACTIVE_DISCORD_UDP.bin",
        "quic_google" => "quic_initial_www_google_com.bin",
        "stun" => "stun.bin",
        "tls_5ka" => "tls_clienthello_5ka_ru.bin",
        "tls_google" => "tls_clienthello_www_google_com.bin",
        "tls_sferum" => "tls_clienthello_www_sferum_ru.bin",
        "tls_steamchat" => "tls_clienthello_steam_chat_com.bin",
        "tls_teamspeak" => "tls_clienthello_teamspeak_com.bin",
        _ => return None,
    })
}
